# model: evaluate each chain; track gender and parent links
def solve(expr):
    t=expr.split(); names=t[0::2]; ops=t[1::2]
    parent={}; spouse={}; sib={}; g={}
    for a,op,b in zip(names,ops,names[1:]):
        if op=='&': g[a]='M'; sib[a]=b
        if op=='x': g[a]='M'; parent.setdefault(b,set()).add(a)
        if op=='?': g[a]='F'; parent.setdefault(b,set()).add(a)
        if op=='!': g[a]='F'; g[b]='M'; spouse[a]=b; spouse[b]=a
    # propagate: spouse of a parent is also parent; siblings share parents
    for _ in range(5):
        for c,ps in list(parent.items()):
            for p in list(ps):
                if p in spouse: ps.add(spouse[p])
        for a,b in sib.items():
            s=parent.get(a,set())|parent.get(b,set())
            if s: parent[a]=set(s); parent[b]=set(s)
    mothers=lambda x:{p for p in parent.get(x,set()) if g.get(p)=='F'}
    return any('W' in mothers(m) for m in mothers('P'))
opts={'A':'W & R ! Y x O ? P','B':'W ? R x Y ! O & P','C':'W ? R ! Y & O x P','D':'W ! R x Y ? O & P'}
assert [k for k,v in opts.items() if solve(v)]==['D']
